-nsMsgDBView::InsertTreeRows(nsMsgViewIndex aIndex, uint32_t aNumRows,
-                            nsMsgKey aKey, nsMsgViewFlagsTypeValue aFlags,
-                            uint32_t aLevel, nsIMsgFolder* aFolder) {
-  if (GetSize() < aIndex) return NS_ERROR_UNEXPECTED;
